using BARANG.Core.Domain.Background;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BARANG.Core.Infrastructure.Persistence.Configurations;
internal sealed class OutboxConfiguration:IEntityTypeConfiguration<OutboxMessage>{public void Configure(EntityTypeBuilder<OutboxMessage>b){b.ToTable("outbox_messages");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.Property(x=>x.EventType).HasColumnName("event_type").HasMaxLength(100);b.Property(x=>x.Payload).HasColumnName("payload").HasColumnType("jsonb");b.Property(x=>x.CorrelationId).HasColumnName("correlation_id").HasMaxLength(100);b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.Property(x=>x.ProcessedAtUtc).HasColumnName("processed_at_utc");b.Property(x=>x.Attempts).HasColumnName("attempts");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.NextAttemptAtUtc).HasColumnName("next_attempt_at_utc");b.Property(x=>x.LastErrorCode).HasColumnName("last_error_code").HasMaxLength(100);b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.Status,x.NextAttemptAtUtc,x.OccurredAtUtc});b.HasIndex(x=>new{x.CompanyId,x.CorrelationId,x.EventType});}}
internal sealed class NotificationConfiguration:IEntityTypeConfiguration<Notification>{public void Configure(EntityTypeBuilder<Notification>b){b.ToTable("notifications");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.RecipientUserId).HasColumnName("recipient_user_id");b.Property(x=>x.Channel).HasColumnName("channel").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.TemplateCode).HasColumnName("template_code").HasMaxLength(100);b.Property(x=>x.Payload).HasColumnName("payload").HasColumnType("jsonb");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.AttemptCount).HasColumnName("attempt_count");b.Property(x=>x.ScheduledAtUtc).HasColumnName("scheduled_at_utc");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.SentAtUtc).HasColumnName("sent_at_utc");b.Property(x=>x.FailedAtUtc).HasColumnName("failed_at_utc");b.Property(x=>x.FailureCode).HasColumnName("failure_code").HasMaxLength(100);b.Property(x=>x.ReadAtUtc).HasColumnName("read_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.RecipientUserId,x.ReadAtUtc,x.CreatedAtUtc});b.HasIndex(x=>new{x.CompanyId,x.Status,x.ScheduledAtUtc});}}
internal sealed class DeadLetterConfiguration:IEntityTypeConfiguration<DeadLetterItem>{public void Configure(EntityTypeBuilder<DeadLetterItem>b){b.ToTable("dead_letter_items");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id");b.Property(x=>x.CompanyId).HasColumnName("company_id");b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.OutboxMessageId).HasColumnName("outbox_message_id");b.Property(x=>x.ErrorCode).HasColumnName("error_code").HasMaxLength(100);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.ReviewedAtUtc).HasColumnName("reviewed_at_utc");b.Property(x=>x.ReviewedByUserId).HasColumnName("reviewed_by_user_id");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.OutboxMessageId}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.Status,x.CreatedAtUtc});b.HasOne<OutboxMessage>().WithMany().HasForeignKey(x=>x.OutboxMessageId).OnDelete(DeleteBehavior.Restrict);}}
